httpRequestBodyGQL.query:
{
  taskDetails(
    from: {{timeEarlierInt}}
    to: {{timeNowInt}}
    filter: { id: { equals: "{{taskId}}" } }
  ) {
    tasks {
      status
      lastWrapupCodeName
      origin
      destination
      direction
      lastAgent {
        id
        name
      }
    }
  }
}

